-- ┌─ HUD // HYPRLAND (Lua config, Hyprland 0.57+) ───────────────┐
-- │ Palette: ~/.dotfiles/theme/PALETTE.md                                   │
-- │ Reference: https://wiki.hypr.land/configuring/                          │
-- └─────────────────────────────────────────────────────────────────────────┘

-- ── tokens ──────────────────────────────────────────────────────────────
-- Everything visual comes from ~/.config/hypr/fui.lua, generated by
-- theme/build.py from theme/tokens.toml (the single source of truth).
-- The fallback below only keeps Hyprland usable if that file is missing.
local ok, T = pcall(dofile, os.getenv("HOME") .. "/.config/hypr/fui.lua")
if not ok or type(T) ~= "table" then
    T = {
        color    = { term_bg = "030506", line = "1A2428", ice = "8FD3DC", ice_hi = "C8EEF2", steel = "6F8FB0" },
        opacity  = { window_active = 0.96, window_inactive = 0.88 },
        blur     = { size = 10, passes = 3, noise = 0.03, contrast = 0.90, brightness = 0.78, vibrancy = 0.30 },
        glow     = { range = 28, alpha = 0.20 },
        geometry = { border = 1, radius = 0, gaps_in = 5, gaps_out = 14 },
        font     = { mono = "JetBrainsMono Nerd Font", size = 10 },
        desktop  = { icon_theme = "Papirus-Dark", cursor_theme = "Adwaita", cursor_size = 24, gtk_base = "adw-gtk3-dark" },
    }
end
-- light / dark: fui mode (SUPER+SHIFT+T) writes the mode file and reloads Hyprland,
-- which swaps the light colours, blur and desktop themes in here.
local mode = "dark"
do
    local dir = os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")
    local f = io.open(dir .. "/fui/mode", "r")
    if f then
        if f:read("*l") == "light" then mode = "light" end
        f:close()
    end
end
if mode == "light" and type(T.light) == "table" then
    for _, key in ipairs({ "color", "blur", "glow", "desktop" }) do
        if type(T.light[key]) == "table" then T[key] = T.light[key] end
    end
end

local function rgba(hex, a) return string.format("rgba(%s%02X)", hex, math.floor(a * 255 + 0.5)) end
local c = {
    bg0     = "rgb(" .. T.color.term_bg .. ")",
    line    = "rgb(" .. T.color.line .. ")",
    teal    = "rgb(" .. T.color.ice .. ")",
}

-- ── programs ────────────────────────────────────────────────────────────
local terminal    = "kitty"
local fileManager = "thunar"
local rofi        = "rofi -config ~/.config/rofi/fui-mode.rasi"   -- fui mode links this to the mode's config
local menu        = rofi .. " -show drun"
local fui         = "$HOME/.local/bin/fui "                         -- the fui command (fui help)
local mod         = "SUPER"

-- ── monitors ────────────────────────────────────────────────────────────
-- Every screen at its preferred mode. Pin one in local.lua, e.g.
--   hl.monitor({ output = "DP-1", mode = "2560x1440@144", position = "0x0", scale = 1 })
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = 1 })

-- ── environment ─────────────────────────────────────────────────────────
hl.env("XCURSOR_SIZE", tostring(T.desktop.cursor_size))
hl.env("XCURSOR_THEME", T.desktop.cursor_theme)
hl.env("HYPRCURSOR_SIZE", tostring(T.desktop.cursor_size))
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
-- No GTK_THEME here: it would pin one mode. GTK picks dark or light from gsettings (set below and by fui mode).

-- ── autostart ───────────────────────────────────────────────────────────
hl.on("hyprland.start", function()
    -- each falls back to the plain program if the fui scripts are missing
    hl.exec_cmd(fui .. "wallpaper start || swaybg -i ~/.config/hypr/wallpaper.png -m fill")  -- live grid, or static
    hl.exec_cmd(fui .. "bar || waybar")                                                 -- compact on small screens
    hl.exec_cmd(fui .. "mode apply --quiet; mako -c ~/.config/mako/fui-mode || mako")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("wl-paste --watch cliphist store")
    hl.exec_cmd(fui .. "sound login")                    -- event sounds (fui sound off to silence)
    hl.exec_cmd(fui .. "tabs")                          -- prepared terminal tabs (kitty/startup.session)
    -- dark or light + theme for GTK and libadwaita apps (they ignore settings.ini)
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme prefer-" .. mode)
    hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme " .. T.desktop.gtk_base)
    hl.exec_cmd("gsettings set org.gnome.desktop.interface icon-theme " .. T.desktop.icon_theme)
    hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-theme " .. T.desktop.cursor_theme)
    hl.exec_cmd("gsettings set org.gnome.desktop.sound theme-name " .. (T.desktop.sound_theme or "ocean"))
    hl.exec_cmd("gsettings set org.gnome.desktop.sound event-sounds true")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface monospace-font-name '" .. T.font.mono .. " " .. T.font.size .. "'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface font-name '" .. T.font.mono .. " " .. T.font.size .. "'")
end)

-- ── look ────────────────────────────────────────────────────────────────
hl.config({
    general = {
        gaps_in  = T.geometry.gaps_in,
        gaps_out = T.geometry.gaps_out,
        border_size = T.geometry.border,
        col = {
            -- teal into blue, like the lit edges of the panels in the references
            active_border   = { colors = { rgba(T.color.ice_hi, 0.87), rgba(T.color.steel, 0.60) }, angle = 135 },
            inactive_border = rgba(T.color.ice, 0.15),
        },
        resize_on_border = true,
        layout = "dwindle",
    },

    -- Frosted glass: windows let the fog behind them through, heavily blurred.
    -- The terminal's own transparency (kitty background_opacity) does most of
    -- the work so text stays sharp; these opacities add a little to everything else.
    decoration = {
        rounding = T.geometry.radius,    -- never rounded

        active_opacity   = T.opacity.window_active,
        inactive_opacity = T.opacity.window_inactive,

        shadow = {
            enabled      = true,
            range        = T.glow.range,
            render_power = 2,               -- soft falloff: a haze, not a hard drop shadow
            color          = rgba(T.color.ice, T.glow.alpha),
            color_inactive = rgba(T.color.steel, 0.06),
        },

        blur = {
            enabled    = true,
            size       = T.blur.size,
            passes     = T.blur.passes,
            noise      = T.blur.noise,
            contrast   = T.blur.contrast,
            brightness = T.blur.brightness,
            vibrancy   = T.blur.vibrancy,
            popups     = true,
        },

        dim_inactive = true,
        dim_strength = 0.05,
    },

    animations = { enabled = true },

    dwindle = {
        preserve_split = true,
    },

    misc = {
        disable_hyprland_logo    = true,
        disable_splash_rendering = true,
        force_default_wallpaper  = 0,
        background_color         = c.bg0,
    },

    input = {
        kb_layout  = "us,ara",
        kb_options = "grp:alt_shift_toggle",  -- Alt+Shift switches English / Arabic
        follow_mouse  = 1,
        sensitivity   = 0,
        accel_profile = "flat",
    },
})

-- ── motion ──────────────────────────────────────────────────────────────
-- "hud" is the demo's --ease curve: fast out, long settle.
hl.curve("hud",  { type = "bezier", points = { {0.16, 1},  {0.3, 1} } })
hl.curve("snap", { type = "bezier", points = { {0.2, 0.9}, {0.1, 1} } })

hl.animation({ leaf = "windowsIn",  enabled = true, speed = 4, bezier = "hud",  style = "popin 92%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 3, bezier = "snap", style = "popin 92%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 4, bezier = "hud" })
hl.animation({ leaf = "border",     enabled = true, speed = 6, bezier = "hud" })
hl.animation({ leaf = "fade",       enabled = true, speed = 3, bezier = "snap" })
hl.animation({ leaf = "layers",     enabled = true, speed = 3, bezier = "hud",  style = "fade" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4, bezier = "hud",  style = "slidefade 12%" })

-- ── global enforcement: every window, including apps installed later ────
-- Clients can ask for rounded corners or their own borders; this overrides them all.
hl.window_rule({
    name  = "fui-geometry",
    match = { class = ".*" },
    rounding    = T.geometry.radius,
    border_size = T.geometry.border,
})

-- terminal tools opened from the bar (fui tui): floating, centred
hl.window_rule({
    name   = "fui-tui",
    match  = { class = "^fui-tui$" },
    float  = true,
    size   = "monitor_w*0.62 monitor_h*0.66",
    center = true,
})

-- ── frosted bar, launcher and notifications ─────────────────────────────
-- Blur what's behind these layers so their translucent panels read as glass.
-- ignore_alpha keeps the blur off the fully transparent gaps between bar segments.
for _, ns in ipairs({ "waybar", "rofi", "notifications" }) do
    hl.layer_rule({
        name  = "glass-" .. ns,
        match = { namespace = "^" .. ns .. "$" },
        blur  = true,
        ignore_alpha = 0.1,
    })
end

-- ── keys ────────────────────────────────────────────────────────────────
local function k(keys) return mod .. " + " .. keys end

hl.bind(k("Return"), hl.dsp.exec_cmd(terminal))
hl.bind(k("D"),      hl.dsp.exec_cmd(menu))
hl.bind(k("E"),      hl.dsp.exec_cmd(fileManager))
hl.bind(k("Y"),      hl.dsp.exec_cmd(fui .. "tui yazi"))             -- files (TUI)
hl.bind(k("A"),      hl.dsp.exec_cmd(fui .. "tui wiremix"))          -- audio mixer
hl.bind(k("N"),      hl.dsp.exec_cmd(fui .. "tui nmtui"))            -- network
hl.bind(k("SHIFT + Return"), hl.dsp.exec_cmd(fui .. "tabs"))     -- the startup tabs again
hl.bind(k("Q"),      hl.dsp.window.close())
hl.bind(k("F"),      hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind(k("V"),      hl.dsp.window.float({ action = "toggle" }))
hl.bind(k("P"),      hl.dsp.window.pseudo())
hl.bind(k("J"),      hl.dsp.layout("togglesplit"))
hl.bind(k("Escape"), hl.dsp.exec_cmd("hyprlock -c ~/.config/hypr/fui-mode-hyprlock.conf || hyprlock"))
hl.bind(k("SHIFT + E"), hl.dsp.exit())
hl.bind(k("SHIFT + V"), hl.dsp.exec_cmd("cliphist list | " .. rofi .. " -dmenu -p CLIP | cliphist decode | wl-copy"))
hl.bind(k("SHIFT + T"), hl.dsp.exec_cmd(fui .. "mode toggle"))        -- light / dark
hl.bind(k("SHIFT + W"), hl.dsp.exec_cmd(fui .. "wallpaper toggle"))   -- live / still wallpaper

-- screenshots: region to clipboard / whole screen to ~/Pictures
hl.bind("Print",         hl.dsp.exec_cmd('grim -g "$(slurp)" - | wl-copy && ' .. fui .. 'sound screenshot'))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("mkdir -p ~/Pictures && grim ~/Pictures/$(date +%Y%m%d-%H%M%S).png && " .. fui .. "sound screenshot"))

-- focus and move with arrows
for _, dir in ipairs({ "left", "right", "up", "down" }) do
    hl.bind(k(dir),             hl.dsp.focus({ direction = dir }))
    hl.bind(k("SHIFT + " .. dir), hl.dsp.window.move({ direction = dir }))
end

-- workspaces 1-9 (shown as 01-09 in the bar)
for i = 1, 9 do
    hl.bind(k(tostring(i)),           hl.dsp.focus({ workspace = i }))
    hl.bind(k("SHIFT + " .. i),       hl.dsp.window.move({ workspace = i }))
end

hl.bind(k("mouse_down"), hl.dsp.focus({ workspace = "e+1" }))
hl.bind(k("mouse_up"),   hl.dsp.focus({ workspace = "e-1" }))
hl.bind(k("mouse:272"),  hl.dsp.window.drag(),   { mouse = true })
hl.bind(k("mouse:273"),  hl.dsp.window.resize(), { mouse = true })

-- media / volume keys
local blip = " && " .. fui .. "sound volume"
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+" .. blip), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-" .. blip),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true })
hl.bind("XF86AudioPlay",        hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext",        hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPrev",        hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- ── machine-specific overrides ──────────────────────────────────────────
-- ~/.config/hypr/local.lua is created by install.sh and ignored by git
-- (monitor layout, NVIDIA env vars). Loaded only if it exists.
pcall(function()
    local path = os.getenv("HOME") .. "/.config/hypr/local.lua"
    local f = io.open(path, "r")
    if f then
        f:close()
        dofile(path)
    end
end)
